VALUES (NULL, NULL, 11654, 'P.T.', 'P.T.', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vyw.jpg', NULL, 'P.T. (Playable Teaser) is a first-person interactive teaser directed by Hideo Kojima and developed by Kojima Productions under the alias of "7780s Studios". It is a psychological survival horror that combined simplicity with an anxiety-inducing environment. The player must investigate the gruesome backstory surrounding the house, and solve puzzles to get to the end game where a cut scene will initiate, and reveal the official teaser trailer for Silent Hills. P.T is widely accepted as a game in its own right, as not only is it considered deeply engaging, but also enjoys significant replay value thanks to its cryptic nature. Due to the cancellation of Silent Hills, it is no longer available for download.', 'https://www.igdb.com/games/pt', '["PlayStation 4"]', NULL, NULL, 0, 1.25599999999999987e+01, '2026-10-19 21:10:52', '2026-10-19 21:10:52')
